#include "RefModel.h"
extern "C" void ref_model_eval(unsigned long long sys_clk,unsigned long long sdram_rst,unsigned long long tim_rp,unsigned long long tim_rcd,unsigned long long tim_refi,unsigned long long tim_rfc,unsigned long long stb,unsigned long long we,unsigned long long address,unsigned long long* ref_ack,unsigned long long* ref_read,unsigned long long* ref_write,unsigned long long* ref_concerned_bank,unsigned long long read_safe,unsigned long long write_safe,unsigned long long precharge_safe,unsigned long long* ref_sdram_cs_n,unsigned long long* ref_sdram_we_n,unsigned long long* ref_sdram_cas_n,unsigned long long* ref_sdram_ras_n,unsigned long long* ref_sdram_adr,unsigned long long* ref_sdram_ba){static VerilatedContext context;static RefModel model(&context);model.sys_clk=sys_clk;model.sdram_rst=sdram_rst;model.tim_rp=tim_rp;model.tim_rcd=tim_rcd;model.tim_refi=tim_refi;model.tim_rfc=tim_rfc;model.stb=stb;model.we=we;model.address=address;model.read_safe=read_safe;model.write_safe=write_safe;model.precharge_safe=precharge_safe;model.eval();*ref_ack=model.ref_ack;*ref_read=model.ref_read;*ref_write=model.ref_write;*ref_concerned_bank=model.ref_concerned_bank;*ref_sdram_cs_n=model.ref_sdram_cs_n;*ref_sdram_we_n=model.ref_sdram_we_n;*ref_sdram_cas_n=model.ref_sdram_cas_n;*ref_sdram_ras_n=model.ref_sdram_ras_n;*ref_sdram_adr=model.ref_sdram_adr;*ref_sdram_ba=model.ref_sdram_ba;}
